<template><view class="page"><view class="hero"><text class="title">精选二手车</text><text class="muted">车况透明 · 方案清晰 · 安心购车</text></view><view class="filters"><input v-model="keyword" placeholder="搜索品牌/车系" @confirm="load"/><button size="mini" @click="load">搜索</button></view><view v-if="!cars.length" class="card muted">暂无在售车辆</view><view v-for="car in cars" :key="car._id" class="card" @click="go(car._id)"><image v-if="car.images&&car.images[0]" :src="car.images[0]" mode="aspectFill" class="cover"/><view class="car-title">{{car.brand}} {{car.series}} <text class="tag">{{car.year}}年</text></view><view class="muted">{{car.mileage}}万公里 · {{car.color}}</view><view class="price">¥{{car.price}} <text>起，月供 ¥{{car.plan?.monthlyPayment||'—'}}</text></view></view></view></template>
<script setup>import {ref,onMounted} from 'vue';const cars=ref([]),keyword=ref('');const db=wx.cloud.database();async function load(){const w=keyword.value?db.command.or([{brand:db.RegExp({regexp:keyword.value,options:'i'})},{series:db.RegExp({regexp:keyword.value,options:'i'})}]):{};const r=await db.collection('vehicles').where({...w,status:'on'}).orderBy('createdAt','desc').get();cars.value=r.data}function go(id){uni.navigateTo({url:'/pages/detail/detail?id='+id})}onMounted(load)</script>
<style scoped>.hero{padding:30rpx 10rpx}.title{display:block;font-size:44rpx;font-weight:700;margin-bottom:10rpx}.filters{display:flex;gap:16rpx;margin-bottom:20rpx}.filters input{background:#fff;padding:18rpx;border-radius:10rpx;flex:1}.cover{width:100%;height:320rpx;border-radius:12rpx;margin-bottom:16rpx}.car-title{font-size:32rpx;font-weight:600;margin-bottom:8rpx}.price{color:#ef4444;font-size:34rpx;font-weight:700;margin-top:16rpx}.price text{font-size:24rpx;font-weight:400;color:#6b7280}</style>
